// SideProjectApis - generated by API Free from the collection "Side project!": 3 APIs, 10 requests that worked in "Try it".
// Types come from one response each: widen int to double, or add ?, where the API can answer differently.
//
//   var apis = new SideProjectApis(new HttpClient());
//   var result = await apis.ExampleAPI.GetUserAsync();

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Net.Http;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Threading;
using System.Threading.Tasks;

/// <summary>Every client of the collection on one HttpClient.</summary>
public sealed class SideProjectApis
{
    public SideProjectApis(HttpClient http, string exampleAPIKey = "DEMO_KEY")
    {
        ExampleAPI = new ExampleAPIClient(http, exampleAPIKey);
        Dogs = new DogsClient(http);
        Dogs2 = new DogsClient2(http);
    }

    public ExampleAPIClient ExampleAPI { get; }
    public DogsClient Dogs { get; }
    public DogsClient2 Dogs2 { get; }
}

public sealed class ExampleAPIClient
{
    private readonly HttpClient _http;
    private readonly string _apiKey;

    /// <param name="apiKey">Defaults to the provider's shared demo key, which is heavily rate limited - pass your own.</param>
    public ExampleAPIClient(HttpClient http, string apiKey = "DEMO_KEY")
    {
        _http = http;
        _apiKey = apiKey;
    }

    /// <summary>GET https://api.example.com/v1/users/2?api_key={key}&amp;lang=en&amp;limit=5&amp;lat=52.52&amp;in=x</summary>
    public async Task<GetUserResponse?> GetUserAsync(int userId = 2, string lang = "en", int limit = 5, double lat = 52.52, string inValue = "x", CancellationToken ct = default)
    {
        var url = $"https://api.example.com/v1/users/{userId}?api_key={Uri.EscapeDataString(_apiKey)}&lang={Uri.EscapeDataString(lang)}&limit={limit}&lat={lat.ToString(CultureInfo.InvariantCulture)}&in={Uri.EscapeDataString(inValue)}";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.TryAddWithoutValidation("X-Trace", "on");
        request.Headers.TryAddWithoutValidation("Authorization", $"Bearer {_apiKey}");
        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<GetUserResponse>(ct);
    }

    /// <summary>POST https://api.example.com/v1/users</summary>
    /// <remarks>Tested with this body: {"name":"morpheus","job":"leader"}</remarks>
    public async Task<PostUsersResponse?> PostUsersAsync(PostUsersRequest body, CancellationToken ct = default)
    {
        var url = $"https://api.example.com/v1/users";
        using var request = new HttpRequestMessage(HttpMethod.Post, url);
        request.Content = JsonContent.Create(body);
        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<PostUsersResponse>(ct);
    }

    /// <summary>GET https://api.example.com/api/json/v1/1/search.php?s=margarita "quoted"</summary>
    public async Task<string> GetSearchAsync(string s = "margarita \"quoted\"", CancellationToken ct = default)
    {
        var url = $"https://api.example.com/api/json/v1/1/search.php?s={Uri.EscapeDataString(s)}";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(ct); // the tested response was not (complete) JSON
    }

    /// <summary>DELETE https://api.example.com/v1/users/2</summary>
    public async Task DeleteUserAsync(int userId = 2, CancellationToken ct = default)
    {
        var url = $"https://api.example.com/v1/users/{userId}";
        using var request = new HttpRequestMessage(HttpMethod.Delete, url);
        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();
    }

    /// <summary>GET https://api.example.com/planetary/apod?api_key=DEMO_KEY&amp;date=2024-01-01</summary>
    public async Task<List<GetApodResponseItem>?> GetApodAsync(string date = "2024-01-01", CancellationToken ct = default)
    {
        var url = $"https://api.example.com/planetary/apod?api_key={Uri.EscapeDataString(_apiKey)}&date={Uri.EscapeDataString(date)}";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<List<GetApodResponseItem>>(ct);
    }

    /// <summary>PUT https://api.example.com/v1/items/9999999999/tags?force=true&amp;ratio=0.50&amp;zip=01234&amp;neg=-3</summary>
    /// <remarks>Tested with this body: a=b&amp;c=d</remarks>
    public async Task<PutTagsResponse?> PutTagsAsync(string body, long itemId = 9999999999, string force = "true", double ratio = 0.50, string zip = "01234", int neg = -3, CancellationToken ct = default)
    {
        var url = $"https://api.example.com/v1/items/{itemId}/tags?force={Uri.EscapeDataString(force)}&ratio={ratio.ToString(CultureInfo.InvariantCulture)}&zip={Uri.EscapeDataString(zip)}&neg={neg}";
        using var request = new HttpRequestMessage(HttpMethod.Put, url);
        request.Headers.TryAddWithoutValidation("X-Api-Key", _apiKey);
        request.Content = new StringContent(body, Encoding.UTF8, "application/x-www-form-urlencoded");
        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<PutTagsResponse>(ct);
    }

    /// <summary>PATCH https://api.example.com/v1/tokens</summary>
    /// <remarks>Tested with this body: {"token":"{key}"}</remarks>
    public async Task<List<int>?> PatchTokensAsync(string body, CancellationToken ct = default)
    {
        var url = $"https://api.example.com/v1/tokens";
        using var request = new HttpRequestMessage(HttpMethod.Patch, url);
        request.Content = new StringContent(body.Replace("{key}", _apiKey), Encoding.UTF8, "application/json");
        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<List<int>>(ct);
    }

    /// <summary>GET https://X.example.com:8443/Public/Cities/new%20york/weather.json?q=a+b%26c&amp;class=1&amp;q=again&amp;flag</summary>
    public async Task<GetWeatherResponse?> GetWeatherAsync(string q = "a b&c", int classValue = 1, string q2 = "again", CancellationToken ct = default)
    {
        var url = $"https://x.example.com:8443/Public/Cities/new%20york/weather.json?q={Uri.EscapeDataString(q)}&class={classValue}&q={Uri.EscapeDataString(q2)}&flag";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<GetWeatherResponse>(ct);
    }
}

